-- Enriquecimiento del padrón con el Excel de Sofi (Pacientes.xlsx, 02/08/2026):
-- teléfonos, emails, DNIs y códigos de vinculación que faltaban. Regla:
-- COALESCE (solo llena huecos, nunca pisa lo cargado); los emails en
-- conflicto se resolvieron a favor de la base (el Gmail es el login).
-- Cargar un código de vinculación avanza el embudo a 'codigo_listo' si el
-- socio estaba esperándolo.
UPDATE socios SET telefono = COALESCE(telefono, '2995320964'), reprocann_codigo = 'KK9Gwzv454839', reprocann_estado = CASE WHEN reprocann_estado IN ('esperando_codigo','sin_iniciar','revisar') THEN 'codigo_listo' ELSE reprocann_estado END, actualizado = datetime('now') WHERE id = 11;
